me"]=[[密道内室(fb609_06)]],["enterable"]=1,["dsc"]=[[入眼便是几根天然的石柱，中间一条细长的石梯曲折朝下，通向一个圆形的地下广场。广场周围列有兵器架、桌案、一张虎皮座椅。传闻当年的明教教主曾于此处修炼阴阳挪移功。]],["down"]=[[fb609_09]],["visible"]=1,["dirIndex"]=0,["unit3"]=[[npc12j]],["unit2"]=[[npc11j]],["unit1"]=[[npc08j]],["canLeave"]=1,["id"]=[[fb609_06]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[居室]],["permission"]=0,["fullName"]=[[居室(fb609_07)]],["enterable"]=1,["dsc"]=[[与中原起居之室大有不同，建于石窟之中，地面铺有红色地毯，床榻乃是由天然岩石所造，四周高大的石柱上放置火盆，以燃烧盆中炭火照明。周围摆设了不少来自波斯的物品，极具异域风味。]],["down"]=[[fb609_10]],["visible"]=1,["dirIndex"]=0,["unit3"]=[[npc12g]],["unit2"]=[[npc11g]],["unit1"]=[[npc08g]],["canLeave"]=1,["id"]=[[fb609_07]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[寝殿]],["permission"]=0,["left"]=[[fb609_03]],["enterable"]=1,["dsc"]=[[殿内正中设有一巨大的圆形软塌，罗帐自天顶而下。软塌周围铺有四五块巨大的红底金纹地毯，毯上又放有许多绣花靠枕。两侧落地宫灯形如枝叶，每叶上托一盏烛火，将殿内照的十分明亮。]],["fullName"]=[[寝殿(fb609_04)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc09a]],["canLeave"]=1,["id"]=[[fb609_04]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[唯光明故殿]],["permission"]=0,["fullName"]=[[唯光明故殿(fb609_05)]],["enterable"]=1,["up"]=[[fb609_03]],["dsc"]=[[殿内红毯铺地，半层高的左右两道石阶通向殿内的铸金宝座。中间一个四四方方的巨型水池，池中锦鲤莲花数不胜数。四周窗饰梁柱多异域风味，层层锦缎帷幕气派非凡。]],["down"]=[[fb609_08]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc06]],["canLeave"]=1,["id"]=[[fb609_05]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb609_25]],["connectPoint"]=0,["name"]=[[风字门]],["permission"]=0,["enterable"]=1,["dsc"]=[[此处乃是风字门教众所聚集之地，属于明教天地风雷四门之一。门内一条铺有红毯的大道笔直向前，通往中央的玉石宝座，两侧罗列石柱，上燃灯火。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[风字门(fb609_24)]],["canLeave"]=1,["id"]=[[fb609_24]],["mapHide"]=0},{["operations"]={},["right"]=[[fb609_26]],["connectPoint"]=0,["enterable"]=1,["down"]=[[fb609_33]],["visible"]=1,["id"]=[[fb609_25]],["rightDown"]=[[fb609_36]],["dsc"]=[[门中弟子早晚朝拜之地，神坛中央放置圣火，周围八根圆柱冲天伫立，凡到此地者，皆心生敬畏之心。]],["permission"]=0,["